        // present mantissa length in words
        auto m = uint32_t(len(z->mant));
        // present mantissa bits; bits > 0
        auto bits = m * _W;
        // bits > z.prec
        if(bits <= z->prec)
        {
            // mantissa fits => nothing to do
            return;
        }


