    // It returns the shift amount. It assumes that len(m) != 0.
    int64_t fnorm(nat m)
    {
        if(debugFloat && (len(m) == 0 || m[len(m) - 1] == 0))
        {
            gocpp::panic("msw of mantissa is 0"_s);
        }
        auto s = nlz(m[len(m) - 1]);
        if(s > 0)
        {
            auto c = shlVU(m, m, s);
            if(debugFloat && c != 0)
            {
                gocpp::panic("nlz or shlVU incorrect"_s);
            }
        }
        return int64_t(s);
    }

